-- mh3sp database schema (SQLite).
--
-- Before 1.0.0 this is the only migration and it is rewritten in place: any change means resetting the database
-- (`scripts/dev.sh --reset`). From 1.0.0 on, migrations only go forward. The reasoning behind each table is in
-- roadmap/M1 schema.md.
--
-- Conventions:
-- - STRICT tables: SQLite enforces the declared column types.
-- - Internal `INTEGER PRIMARY KEY` ids never leave the database; what people reference has a `public_id`
--   (UUID v7, 16 bytes, generated by the server: SQLite has no UUID functions).
-- - Enumerations are TEXT with a CHECK. Format checks use GLOB (SQLite has no regular expressions by default).
-- - Texts are a dictionary in the code, settings live in config.toml (both come to the database with the website,
--   M8). Terms are overrides of the terms built into the code.
-- - Timestamps are UTC, 'YYYY-MM-DD HH:MM:SS' text (CURRENT_TIMESTAMP).
-- - Foreign keys are enforced because the server enables them on every connection (off by default in SQLite).

-- Overrides of the terms and sub-terms; each edit is a new row whose id is the version sent to the console.
-- The console remembers the version it accepted and shows the terms again when the server's differs; ids only
-- grow, so an edit is always shown again.
-- Current: latest row for (kind, console language) -> latest for (kind, 'en') -> built-in.
CREATE TABLE terms (
    -- AUTOINCREMENT: without it SQLite may reuse the highest id after a deletion, and a version would go down.
    -- From 2: the terms built into the code are version 1 (sequence seeded below), so the first override is newer.
    -- At most 4294967295 (2^32 - 1): the version travels as a 32-bit unsigned field (AnsTermsVersion).
    id          INTEGER PRIMARY KEY AUTOINCREMENT CHECK (id BETWEEN 2 AND 4294967295),
    kind        TEXT NOT NULL CHECK (kind IN ('terms', 'subterms')),
    -- ISO 639-1: the game's languages are fixed (en, fr, de, it, es; ja later) and have no regional variants.
    language    TEXT NOT NULL CHECK (language GLOB '[a-z][a-z]'),
    value       TEXT NOT NULL,
    created_at  TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
) STRICT;
CREATE INDEX terms_current ON terms (kind, language, id DESC);

-- World servers, server types (with their HR limits) and the world layout are not in the database: they are game
-- constants in the code, optionally overridden by `config.toml` at startup.

-- A console, identified by HMAC-SHA256(pepper, online support code); the code itself is never stored.
CREATE TABLE consoles (
    id                  INTEGER PRIMARY KEY,
    public_id           BLOB NOT NULL UNIQUE CHECK (length(public_id) = 16),
    support_code_hmac   BLOB NOT NULL UNIQUE CHECK (length(support_code_hmac) = 32),
    region              TEXT NOT NULL CHECK (region IN ('RMHP08', 'RMHE08')),
    created_at          TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_seen_at        TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
) STRICT;

-- One of a console's 6 Capcom ID slots (an online identity a hunter of the save plays under).
-- Another hunter taking the slot overwrites name and profile and drops its social links; the Capcom ID and its
-- moderation records stay.
CREATE TABLE hunters (
    id              INTEGER PRIMARY KEY,
    public_id       BLOB NOT NULL UNIQUE CHECK (length(public_id) = 16),
    console_id      INTEGER NOT NULL REFERENCES consoles (id) ON DELETE CASCADE,
    slot            INTEGER NOT NULL CHECK (slot BETWEEN 1 AND 6),
    capcom_id       TEXT NOT NULL UNIQUE CHECK (length(capcom_id) = 6 AND capcom_id NOT GLOB '*[^0-9A-Z]*'),
    name            BLOB NOT NULL,     -- as the game sends it (may be Shift-JIS)
    created_at      TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_seen_at    TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (console_id, slot)
) STRICT;
CREATE INDEX hunters_console ON hunters (console_id);

-- Initial data.

-- Terms overrides start at 2: AUTOINCREMENT continues after the sequence's value.
INSERT INTO sqlite_sequence (name, seq) VALUES ('terms', 1);
